open('algo.py','w').write(src[:idx] + '''# --------------------------------------------------------------------------
# Exact planning, guard certification and certificate audit (contract 3.1)
# --------------------------------------------------------------------------

def dijkstra(nstates, indptr, dsts, ws, sources):
    """Lexicographic (bound, age) Dijkstra over packed integer labels."""
    dist = [topo.INF] * nstates
    pv = [0] * nstates
    pk = [-1] * nstates
    heap = [(0, s) for s in sources]
    heapq.heapify(heap)
    push = heapq.heappush
    pop = heapq.heappop
    settled = 0
    while heap:
        d, u = pop(heap)
        if d > dist[u]:
            continue
        settled += 1
        for j in range(indptr[u], indptr[u + 1]):
            v = dsts[j]
            nd = d + ws[j]
            if nd < dist[v]:
                dist[v] = nd
                pv[v] = u
                pk[v] = j
                push(heap, (nd, v))
    return dist, pv, pk, settled


def _stats(F, dist, settled, with_warmup=False):
    """All-time peak, reachability and (optionally) warmup-relevant age."""
    if settled < F.nstates:
        if with_warmup:
            return None, False, None
        return None, False
    best = -1
    vt = F.w_wb.tolist()
    m = -1
    N = F.n
    s = 0
    for d in dist:
        val = (d >> topo.AGE_SH) + vt[s]
        if val > best:
            best = val
        if with_warmup:
            v = (d & topo.AGE_MASK) - s // N
            if v > m:
                m = v
        s += 1
    if with_warmup:
        return best, True, m
    return best, True


def _matrices(F, dist, pv, pk, kinds):
    P, N = F.P, F.n
    anch = F.anch.T.reshape(-1).tolist()
    bflat = [None] * F.nstates
    aflat = [None] * F.nstates
    pflat = [None] * F.nstates
    for s in range(F.nstates):
        d = dist[s]
        if d >= topo.INF:
            continue
        bflat[s] = d >> topo.AGE_SH
        aflat[s] = d & topo.AGE_MASK
        if not anch[s]:
            pflat[s] = [pv[s], kinds[pk[s]]]
    bounds = [bflat[p * N:(p + 1) * N] for p in range(P)]
    ages = [aflat[p * N:(p + 1) * N] for p in range(P)]
    pred = [pflat[p * N:(p + 1) * N] for p in range(P)]
    return bounds, ages, pred


def _warmup(F, dist):
    m = -1
    N = F.n
    s = 0
    for d in dist:
        v = (d & topo.AGE_MASK) - s // N
        if v > m:
            m = v
        s += 1
    if m <= 0:
        return 0
    P = F.P
    return -(-m // P)


def solve_fabric(profile, cal, fabric):
    """Exact envelope, peaks, guard selection, witness and warmup cycle."""
    F = topo.Fabric(fabric)
    H, _C = para.hop_tables(cal['upper_ps'], profile['jitter_ps'])
    F.build_edges(H)
    guards = fabric['guards_ns']
    rconf = int(fabric['reconfig_ns']) * 1000
    npk = len(guards)
    peaks = [None] * npk
    best = None
    for idx in range(npk):
        if idx and peaks[idx - 1] is None:
            break
        g = guards[idx]
        indptr, dst, w, _k = F.csr(g)
        dist, pv, pk, settled = dijkstra(F.nstates, indptr, dst, w,
                                         F.anchor_states.tolist())
        del indptr, dst, w
        peak, allfin = _stats(F, dist, settled)
        peaks[idx] = peak
        if allfin and peak is not None and peak + rconf <= g * 1000 and best is None:
            best = (idx, g, dist, pv, pk)
        else:
            del dist, pv, pk
    bounds = ages = pred = None
    warmup = None
    guard = None
    if best is not None:
        idx, g, dist, pv, pk = best
        _i, _d, _w, kinds = F.csr(g, want_kind=True)
        del _i, _d, _w
        bounds, ages, pred = _matrices(F, dist, pv, pk, kinds)
        warmup = _warmup(F, dist)
        guard = g
        del dist, pv, pk
    return {'period': F.P, 'peaks': peaks, 'guard': guard, 'bounds': bounds,
            'ages': ages, 'pred': pred, 'warmup': warmup}


def compile_plan(profile, fabric):
    cal = para.calibrate(profile)
    if cal['status'] != 'ok':
        return {'status': 'inconsistent', 'cycle': cal['cycle']}
    res = solve_fabric(profile, cal, fabric)
    return {'status': 'ok', 'profile': cal, 'period_rounds': res['period'],
            'peaks_as': res['peaks'], 'guard_ns': res['guard'],
            'bounds_as': res['bounds'], 'age_rounds': res['ages'],
            'pred': res['pred'], 'warmup_cycle': res['warmup']}


# ------------------------------------------------------------------ audit
def _is_int(x):
    return type(x) is int


def _check_cycle(cyc, profile):
    if not isinstance(cyc, list):
        return False
    K = int(profile['groups'])
    if len(cyc) < 1 or len(cyc) > K:
        return False
    src, dst, w = para.constraint_arrays(profile['measurements'])
    sl = src.tolist(); dl = dst.tolist(); wl = w.tolist()
    M2 = len(sl)
    prev = None
    total = 0
    for c in cyc:
        if not _is_int(c) or c < 0 or c >= M2:
            return False
        if prev is not None and sl[c] != prev:
            return False
        prev = dl[c]
        total += wl[c]
    if prev is None or sl[cyc[0]] != prev:
        return False
    return total < 0


def _check_cal_artifact(art, profile):
    if not isinstance(art, dict) or art.get('status') != 'ok':
        return False
    if set(art.keys()) != {'status', 'upper_ps', 'pred'}:
        return False
    K = int(profile['groups'])
    meas = profile['measurements']
    up = art['upper_ps']
    pr = art['pred']
    if not isinstance(up, list) or len(up) != K:
        return False
    if not isinstance(pr, list) or len(pr) != K:
        return False
    for row in up:
        if not isinstance(row, list) or len(row) != K:
            return False
        for x in row:
            if not _is_int(x) or x > 10 ** 30 or x < -10 ** 30:
                return False
    for prow in pr:
        if not isinstance(prow, list) or len(prow) != K:
            return False
        for x in prow:
            if x is not None and not _is_int(x):
                return False
    for a in range(K):
        if up[a][a] != 0 or pr[a][a] is not None:
            return False
    for a in range(K):
        row = up[a]
        for x, y, low, high in meas:
            d = row[x] - row[y]
            if d < low or d > high:
                return False
    src, dst, w = para.constraint_arrays(meas)
    sl = src.tolist(); dl = dst.tolist(); wl = w.tolist()
    M2 = len(sl)
    for a in range(K):
        for b in range(K):
            if b == a:
                continue
            cur = b
            total = 0
            steps = 0
            while cur != a:
                c = pr[a][cur]
                if not _is_int(c) or c < 0 or c >= M2:
                    return False
                if dl[c] != cur:
                    return False
                total += wl[c]
                cur = sl[c]
                steps += 1
                if steps > K:
                    return False
            if total != up[a][b]:
                return False
    return True


def _flat_matrix(mat, P, N):
    """Flatten a P x N artifact matrix; returns None on a shape defect."""
    if not isinstance(mat, list) or len(mat) != P:
        return None
    out = [None] * (P * N)
    for p in range(P):
        row = mat[p]
        if not isinstance(row, list) or len(row) != N:
            return None
        base = p * N
        for i in range(N):
            out[base + i] = row[i]
    return out


def audit(profile, fabric, proposal):
    try:
        return {'valid': _audit(profile, fabric, proposal)}
    except (KeyError, TypeError, ValueError, IndexError, OverflowError):
        return {'valid': False}


def _audit(profile, fabric, proposal):
    if not isinstance(proposal, dict):
        return False
    st = proposal.get('status')
    cal = para.calibrate(profile)
    inconsistent = cal['status'] != 'ok'
    if st == 'inconsistent':
        if set(proposal.keys()) != {'status', 'cycle'}:
            return False
        return (not inconsistent) and _check_cycle(proposal['cycle'], profile)
    if st != 'ok' or inconsistent:
        return False
    if set(proposal.keys()) != {'status', 'profile', 'period_rounds', 'peaks_as',
                                'guard_ns', 'bounds_as', 'age_rounds', 'pred',
                                'warmup_cycle'}:
        return False
    if not _check_cal_artifact(proposal['profile'], profile):
        return False
    F = topo.Fabric(fabric)
    H, _C = para.hop_tables(cal['upper_ps'], profile['jitter_ps'])
    F.build_edges(H)
    truth = solve_fabric(profile, cal, fabric)
    P, N = F.P, F.n
    if proposal.get('period_rounds') != P:
        return False
    peaks = proposal.get('peaks_as')
    if not isinstance(peaks, list) or len(peaks) != len(truth['peaks']):
        return False
    for got, want in zip(peaks, truth['peaks']):
        if want is None:
            if got is not None:
                return False
        else:
            if not _is_int(got) or got != want:
                return False
    if proposal.get('guard_ns') != truth['guard']:
        return False
    if truth['guard'] is None:
        for key in ('bounds_as', 'age_rounds', 'pred', 'warmup_cycle'):
            if proposal.get(key) is not None:
                return False
        return True
    # bound matrices must match exactly, cell for cell
    gotb = _flat_matrix(proposal.get('bounds_as'), P, N)
    gota = _flat_matrix(proposal.get('age_rounds'), P, N)
    gotp = _flat_matrix(proposal.get('pred'), P, N)
    if gotb is None or gota is None or gotp is None:
        return False
    tb = _flat_matrix(truth['bounds'], P, N)
    ta = _flat_matrix(truth['ages'], P, N)
    for s in range(F.nstates):
        if gotb[s] is None:
            if tb[s] is not None:
                return False
            if gota[s] is not None or gotp[s] is not None:
                return False
            continue
        if not _is_int(gotb[s]) or not _is_int(gota[s]):
            return False
        if gotb[s] > 10 ** 30 or gotb[s] < -10 ** 30:
            return False
        if gota[s] > 10 ** 30 or gota[s] < -10 ** 30:
            return False
        if gotb[s] != tb[s] or gota[s] != ta[s]:
            return False
    if proposal.get('warmup_cycle') != truth['warmup']:
        return False
    return _check_witness(F, H, gotb, gota, gotp, truth['guard'])


def _check_witness(F, H, bflat, aflat, pflat, guard):
    """Validate predecessor labels as an attaining optimal lineage family."""
    import numpy as np
    P, N, T, S = F.P, F.n, F.T, F.S
    nst = F.nstates
    anch = F.anch.T.reshape(-1)
    cells = []
    us = []
    ks = []
    for s in range(nst):
        if bflat[s] is None:
            continue
        if anch[s]:
            if bflat[s] != 0 or aflat[s] != 0 or pflat[s] is not None:
                return False
            continue
        pr = pflat[s]
        if not isinstance(pr, list) or len(pr) != 2:
            return False
        u, k = pr
        if not _is_int(u) or not _is_int(k):
            return False
        if u < 0 or u >= nst:
            return False
        if bflat[u] is None:
            return False
        cells.append(s)
        us.append(u)
        ks.append(k)
    if not cells:
        return True
    cells = np.asarray(cells, dtype=np.int64)
    us = np.asarray(us, dtype=np.int64)
    ks = np.asarray(ks, dtype=np.int64)
    p_arr = cells // N
    i_arr = cells - p_arr * N
    pu = us // N
    iu = us - pu * N
    wb = np.zeros(len(cells), dtype=np.int64)
    wa = np.zeros(len(cells), dtype=np.int64)
    ok = np.zeros(len(cells), dtype=bool)
    wmask = ks == -1
    if wmask.any():
        idx = np.nonzero(wmask)[0]
        good = (iu[idx] == i_arr[idx]) & (pu[idx] == (p_arr[idx] - 1) % P)
        ok[idx] = good
        if good.any():
            g = idx[good]
            wb[g] = F.w_wb[us[g]]
            wa[g] = 1
    tmask = (ks >= 0)
    if tmask.any():
        idx = np.nonzero(tmask)[0]
        kc = ks[idx]
        good = kc < 2 * F.nl
        ok[idx] = False
        kc = kc[good]
        idx = idx[good]
        if len(idx):
            sn = F.dc_src[kc]; dn = F.dc_dst[kc]
            gs = F.dc_gs[kc]; gd = F.dc_gd[kc]
            d = F.dc_d[kc]; q = F.dc_q[kc]
            r = d // T
            m = d % T
            L = r + (m > 0).astype(np.int64)
            Delta = L + q
            good2 = (iu[idx] == sn) & (i_arr[idx] == dn) & \
                    (((pu[idx] + Delta) % P) == p_arr[idx])
            base = idx[good2]
            kc = kc[good2]
            sn = sn[good2]; dn = dn[good2]; gs = gs[good2]; gd = gd[good2]
            d = d[good2]; q = q[good2]; r = r[good2]; m = m[good2]
            Delta = Delta[good2]
            puu = pu[base]
            rho = F.rho_arr[puu]
            elig = (rho >= guard) & (rho + d + guard <= S)
            blpre = F.blpre
            bstride = P + topo.BLW + 1
            ll = kc >> 1
            bl = (blpre[ll, puu + (d + T - 1) // T] - blpre[ll, puu]) == 0
            elig = elig & bl
            gsel = base[elig]
            if len(gsel):
                ok[gsel] = True
                hval = H[gs[elig], gd[elig]]
                vx_flat, cv_flat, vxs, cvs = F.circular_tables()
                sidx = puu[elig] + r[elig] + (m[elig] > 0).astype(np.int64)
                ag = T * (cv_flat[dn[elig] * cvs + sidx + q[elig]] -
                          cv_flat[dn[elig] * cvs + sidx])
                ag = ag + np.where(m[elig] > 0,
                                   vx_flat[dn[elig] * vxs + puu[elig] + r[elig]] *
                                   (T - m[elig]), 0)
                wb[gsel] = hval + ag
                wa[gsel] = Delta[elig]
    if not ok.all():
        return False
    # label equations
    if not np.array_equal(bflat_arr(cells, bflat), None) if False else True:
        pass
    bsrc = np.asarray([bflat[u] for u in us], dtype=np.int64)
    asrc = np.asarray([aflat[u] for u in us], dtype=np.int64)
    bdst = np.asarray([bflat[s] for s in cells], dtype=np.int64)
    adst = np.asarray([aflat[s] for s in cells], dtype=np.int64)
    if not (np.array_equal(bdst, bsrc + wb) and np.array_equal(adst, asrc + wa)):
        return False
    # every finite witness terminates at an anchor: walk in age order
    order = np.argsort(adst, kind='stable')
    rooted = [False] * nst
    for s in anch_list(F):
        rooted[s] = True
    pos = 0
    cellsl = cells.tolist()
    usl = us.tolist()
    for oi in order.tolist():
        s = cellsl[oi]
        u = usl[oi]
        if not rooted[u]:
            return False
        rooted[s] = True
    return True


def anch_list(F):
    return F.anchor_states.tolist()


def bflat_arr(cells, bflat):
    return None
''')
