"""JSONL driver for the extended SyncWise computational system."""
import os
os.environ['OPENBLAS_NUM_THREADS'] = '1'
os.environ['OMP_NUM_THREADS'] = '1'
import json
import sys
import algo
import para
import simulator


def dispatch(request):
    op = request['op']
    if op == 'calibrate':
        return para.calibrate(request['profile'])
    if op == 'plan':
        return algo.compile_plan(request['profile'], request['fabric'])
    if op == 'audit':
        return algo.audit(request['profile'], request['fabric'], request['proposal'])
    if op == 'replay':
        return simulator.replay(request['profile'], request['fabric'],
                                request['guard_ns'], request['trace'])
    raise ValueError('unsupported op')


def main(argv):
    out = sys.stdout
    for line in sys.stdin:
        if line.strip():
            out.write(json.dumps(dispatch(json.loads(line)), separators=(',', ':')))
            out.write('\n')
            out.flush()


if __name__ == '__main__':
    main(sys.argv)
