                if isinstance(pr[i][j], list):
                    pr[i][j][1] = pr[i][j][1] + 1; done = True; break
            if done: break
        if algo.audit(prof, fab, p) != {'valid': False}: fails.append('predkind')
        p = copy.deepcopy(plan)
        p['period_rounds'] += 1
        if algo.audit(prof, fab, p) != {'valid': False}: fails.append('period')
        p = copy.deepcopy(plan)
        p['guard_ns'] = None
        if algo.audit(prof, fab, p) != {'valid': False}: fails.append('guardnull')
    p = copy.deepcopy(plan)
    p['profile']['upper_ps'][0][0] = 5
