    p = copy.deepcopy(plan)
    p['profile']['upper_ps'][0][-1] += 1 if len(p['profile']['upper_ps'][0]) > 1 else 0
    if algo.audit(prof, fab, p) != {'valid': False}: fails.append('uppercell')
    p = copy.deepcopy(plan)
    p['bounds_as'] = None
    if algo.audit(prof, fab, p) != {'valid': False}: fails.append('nullbounds')
    if fails:
