"""Build alternative valid witnesses and check the audit accepts them."""
import random, sys, json
sys.path.insert(0, '/workspace/submission'); sys.path.insert(0, '/workspace/tmp')
import para, algo, ref as refmod, cmp_plan, itertools


def alt_pred(prof, fab, guard, rng):
    """Reference-derived alternative optimal predecessor choice."""
    cal = para.calibrate(prof)
    R = refmod.Ref(prof, fab)
    hmax = 24 * R.P * R.n + 64
    B, A, warm, lab = R.envelope(cal['upper_ps'], guard, hmax)
    P, N = R.P, R.n
    Hm = refmod.hop(prof, cal['upper_ps'])
    # candidate optimal steps per target cell
    cands = {}
    for pu in range(P):
        for j in range(N):
            if B[pu][j] is None:
                continue
            for (adv, i, wb, wa) in R.steps(pu, j, guard, Hm):
                p = (pu + adv) % P
                key = (p, i)
                if B[p][i] is None:
                    continue
                if B[pu][j] + wb == B[p][i] and A[pu][j] + wa == A[p][i]:
                    cands.setdefault(key, []).append((((pu * N + j)), -1 if adv == 1 and j == i and wb == R.v[i][pu] * T_ if False else 0, 0))
    return None


def alt_plan(prof, fab, guard, rng):
    cal = para.calibrate(prof)
    R = refmod.Ref(prof, fab)
    hmax = 24 * R.P * R.n + 64
    B, A, warm, lab = R.envelope(cal['upper_ps'], guard, hmax)
    P, N = R.P, R.n
    Hm = refmod.hop(prof, cal['upper_ps'])
    # waiting step identified by advance 1 and same node
    inc = {}
    for pu in range(P):
        for j in range(N):
            if B[pu][j] is None:
                continue
            for (adv, i, wb, wa) in R.steps(pu, j, guard, Hm):
                p = (pu + adv) % P
                if B[p][i] is None:
                    continue
                if B[pu][j] + wb == B[p][i] and A[pu][j] + wa == A[p][i]:
                    iswait = (adv == 1 and i == j)
                    kind = -1 if iswait else None
                    if not iswait:
                        # find the directed code
                        kind = None
                        nominal = R.O + pu * R.T
                        sl = R.slices[(nominal // R.S) % R.Q]
                        rho = nominal % R.S
                        for l in sl:
                            lk = fab['links'][l]
                            (n0, s0, g0), (n1, s1, g1) = lk['ends']
                            for dirn in (0, 1):
                                if dirn == 0:
                                    src, gs, dst, gd = n0, g0, n1, g1
                                    d, q = lk['delay_ns'][0], lk['defer_rounds'][0]
                                else:
                                    src, gs, dst, gd = n1, g1, n0, g0
                                    d, q = lk['delay_ns'][1], lk['defer_rounds'][1]
                                if src != j or dst != i:
                                    continue
                                if rho < guard or rho + d + guard > R.S:
                                    continue
                                rr = d // R.T
                                m = d % R.T
                                L = rr + (1 if m else 0)
                                if any(x % P in R.bl[l] for x in range(pu, pu + L)):
                                    continue
                                if L + q != adv:
                                    continue
                                kind = 2 * l + dirn
                        if kind is None:
                            continue
                    inc.setdefault((p, i), []).append((pu * N + j, kind))
    anch = [[False] * P for _ in range(N)]
    for node, st, en in fab['anchors']:
        for p in range(st, en):
            anch[node][p] = True
    pred = [[None] * N for _ in range(P)]
    for p in range(P):
        for i in range(N):
            if B[p][i] is None:
                continue
            if anch[i][p]:
                continue
            c = inc.get((p, i))
            if not c:
                return None
            pred[p][i] = list(c[rng.randrange(len(c))])
    return {'status': 'ok', 'profile': cal, 'period_rounds': P,
            'peaks_as': [None] * len(fab['guards_ns']), 'guard_ns': guard,
            'bounds_as': B, 'age_rounds': A, 'pred': pred,
            'warmup_cycle': warm}


def main(seed0, count):
    rng = random.Random(seed0)
    ok = 0
    bad = 0
    for it in range(count):
        g = cmp_plan.gen(rng)
        if g is None:
            continue
        prof, fab = g
        cal = para.calibrate(prof)
        if cal['status'] != 'ok':
            continue
        for guard in fab['guards_ns']:
            plan = algo.compile_plan(prof, fab)
            if plan['status'] != 'ok' or plan['guard_ns'] != guard:
                continue
            alt = alt_plan(prof, fab, guard, rng)
            if alt is None:
                continue
            # fill peaks with the true ones so that only the witness differs
            alt['peaks_as'] = plan['peaks_as']
            r = algo.audit(prof, fab, alt)
            if r != {'valid': True}:
                bad += 1
                print('ALT REJECTED', it, guard)
                print(json.dumps(prof)); print(json.dumps(fab))
                if bad >= 2:
                    return
            else:
                ok += 1
    print('alternative witnesses accepted', ok, 'rejected', bad)


if __name__ == '__main__':
    main(int(sys.argv[1]), int(sys.argv[2]))
