"""End-to-end driver test: types, flushing, multiple requests."""
import json, subprocess, sys, random
sys.path.insert(0, '/workspace/submission'); sys.path.insert(0, '/workspace/tmp')
import para, algo, cmp_plan, simulator

def types_ok(x, path=''):
    if x is None or isinstance(x, (str, bool)):
        return True
    if isinstance(x, float):
        print('FLOAT at', path); return False
    if isinstance(x, int):
        return True
    if isinstance(x, list):
        return all(types_ok(v, path + '[]') for v in x)
    if isinstance(x, dict):
        return all(isinstance(k, str) and types_ok(v, path + '.' + k) for k, v in x.items())
    print('BAD TYPE', type(x), path); return False


def main(seed0, count):
    rng = random.Random(seed0)
    reqs = []
    exps = []
    made = 0
    while made < count:
        g = cmp_plan.gen(rng)
        if g is None:
            continue
        prof, fab = g
        made += 1
        pick = rng.random()
        if pick < 0.3:
            reqs.append({'op': 'calibrate', 'profile': prof})
        elif pick < 0.6:
            reqs.append({'op': 'plan', 'profile': prof, 'fabric': fab})
        elif pick < 0.8:
            plan = algo.compile_plan(prof, fab)
            if rng.random() < 0.5 and plan['status'] == 'ok' and plan['bounds_as']:
                B = plan['bounds_as']
                for row in B:
                    for i, c in enumerate(row):
                        if c is not None:
                            row[i] = c + 1
                            break
                    else:
                        continue
                    break
            reqs.append({'op': 'audit', 'profile': prof, 'fabric': fab, 'proposal': plan})
        else:
            import cmp_replay
            R = rng.randint(0, 20)
            tr = cmp_replay.gen_trace(rng, prof, fab, R)
            if tr is None:
                made -= 1
                continue
            reqs.append({'op': 'replay', 'profile': prof, 'fabric': fab,
                         'guard_ns': fab['guards_ns'][0], 'trace': tr})
    inp = ''.join(json.dumps(r, separators=(',', ':')) + '\n' for r in reqs)
    p = subprocess.run([sys.executable, '-B', '/workspace/submission/main.py'],
                       input=inp.encode(), stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=600)
    if p.returncode:
        print('FAIL rc', p.returncode, p.stderr.decode()[:2000]); return
    lines = p.stdout.decode().splitlines()
    if len(lines) != len(reqs):
        print('FAIL count', len(lines), len(reqs)); return
    ok = True
    for i, (r, ln) in enumerate(zip(reqs, lines)):
        obj = json.loads(ln)
        if not types_ok(obj, str(i)):
            ok = False
        if r['op'] == 'audit':
            want = algo.audit(r['profile'], r['fabric'], r['proposal'])
            if obj != want:
                print('audit mismatch', i, obj, want); ok = False
        if r['op'] == 'calibrate':
            if obj != para.calibrate(r['profile']):
                print('calibrate mismatch', i); ok = False
        if r['op'] == 'plan':
            if obj != algo.compile_plan(r['profile'], r['fabric']):
                print('plan mismatch', i); ok = False
        if r['op'] == 'replay':
            if obj != simulator.replay(r['profile'], r['fabric'], r['guard_ns'], r['trace']):
                print('replay mismatch', i); ok = False
    print('driver requests', len(reqs), 'ok' if ok else 'FAIL')

if __name__ == '__main__':
    main(int(sys.argv[1]), int(sys.argv[2]))
